-- Jeu de LecteurRetourAudience et EcrivainRetourAudience (« Retour d'audience », PROC_RETAUD), lot 7 du plan « RIG v3 100 %
-- fonctionnel » (plan-676a4b19). Identifiants 1 700 xxx (lot 7), roles 2026x17xxx. Les instances n'ont PAS de code affaire :
-- elles restent hors des listes d'instances des autres lots (MJUD, JOIN, XLIEN... joignent CODE_AFFAIRE).
-- Les tables V2 lues, aux types de RIG_DEV (Source\BaseDeDonnees\RigDatabase\dbo\Tables\*.sql de RigApplication), seulement les
-- colonnes lues ou ecrites. Une table deja creee par un jeu joue avant recoit les colonnes qui lui manquent (nullables, ou avec
-- un DEFAULT : d'autres jeux y inserent sans elles), et les lignes passent par sp_executesql (une colonne ajoutee dans ce lot
-- d'instructions n'existe pas encore quand SQL Server le compile). PAS d'IDENTITY : les jeux inserent leurs identifiants.
-- Ce qui est retenu ou ecarte, et pourquoi : PROC_RETAUD.attendu ; recherches : PROC_RETAUD.recherches ; gestes : PROC_RETAUD.gestes.
IF OBJECT_ID(N'v2.INSTANCE') IS NULL
    CREATE TABLE v2.INSTANCE (INSTN_ID_INSTN int NOT NULL PRIMARY KEY, INSTN_NUM_ROLE varchar(11) NULL, INSTN_NOM_COURANT varchar(250) NULL);
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TYPE_INSTANCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TYPE_INSTANCE varchar(2) NULL;
IF OBJECT_ID(N'v2.AUDIENCE_CABINET') IS NULL
    CREATE TABLE v2.AUDIENCE_CABINET (AUDNC_ID_ADNC int NOT NULL PRIMARY KEY, AUDNC_DATE datetime NULL, AUDNC_HEURE varchar(5) NULL);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_AUDIENCE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_AUDIENCE bit NOT NULL DEFAULT (1);
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_CHAMBRE') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_CHAMBRE varchar(5) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_SECTION') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_SECTION varchar(10) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_ID_JUG') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_ID_JUG int NULL;
IF OBJECT_ID(N'v2.APPEL_AFFAIRE') IS NULL
    CREATE TABLE v2.APPEL_AFFAIRE (APPAF_ID_APPAF int NOT NULL PRIMARY KEY, APPAF_ID_INSTN int NULL, APPAF_NUM_ORDRE smallint NOT NULL,
        APPAF_ID_ADNC int NOT NULL);
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_ID_CMAUD') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_ID_CMAUD int NULL;
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_TYPE_CLASSEMENT') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_TYPE_CLASSEMENT varchar(5) NULL;
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_NUM_APPEL') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_NUM_APPEL varchar(6) NULL;
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_ETAT_PREPARATION') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_ETAT_PREPARATION varchar(1) NULL;
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_ETAT_RETOUR') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_ETAT_RETOUR varchar(1) NULL;
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_CODE_PLUMITIF') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_CODE_PLUMITIF varchar(16) NULL;
IF OBJECT_ID(N'v2.TYPE_CLASSEMENT') IS NULL
    CREATE TABLE v2.TYPE_CLASSEMENT (R_TYPECLASSE_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_TYPECLASSE_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_TYPECLASSE_PRONONCE bit NOT NULL DEFAULT (0));
IF OBJECT_ID(N'v2.CODE_PLUMITIF') IS NULL
    CREATE TABLE v2.CODE_PLUMITIF (R_CODEPLUMIT_VALEUR varchar(16) NOT NULL PRIMARY KEY, R_CODEPLUMIT_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_CODEPLUMIT_UTILISABLE_SAISIE bit NOT NULL DEFAULT (1), R_CODEPLUMIT_CODE_EVE_PRO varchar(10) NULL, R_CODEPLUMIT_AVEC_AUDIENCE varchar(1) NULL,
        R_CODEPLUMIT_TYPE_CLASSEMENT varchar(5) NULL, R_CODEPLUMIT_DELIBERE bit NOT NULL DEFAULT (0), R_CODEPLUMIT_PRONONCE bit NOT NULL DEFAULT (0),
        R_CODEPLUMIT_CHAMBRE varchar(5) NULL, R_CODEPLUMIT_DELIBERE_REPOUSSE bit NOT NULL DEFAULT (0), R_CODEPLUMIT_RENVOI bit NOT NULL DEFAULT (0),
        R_CODEPLUMIT_COMPATIBLE_OP bit NOT NULL DEFAULT (0), R_CODEPLUMIT_COMPATIBLE_JC bit NOT NULL DEFAULT (0),
        R_CODEPLUMIT_COMPATIBLE_CX bit NOT NULL DEFAULT (0), R_CODEPLUMIT_COMPATIBLE_REF bit NOT NULL DEFAULT (0),
        R_CODEPLUMIT_COMPATIBLE_PC bit NOT NULL DEFAULT (0), R_CODEPLUMIT_COMPATIBLE_PRV bit NOT NULL DEFAULT (0));
IF OBJECT_ID(N'v2.CHAMBRE') IS NULL
    CREATE TABLE v2.CHAMBRE (R_CHAMBRE_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_CHAMBRE_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_CHAMBRE_AVEC_COMPO bit NOT NULL DEFAULT (1));
IF OBJECT_ID(N'v2.SECTION') IS NULL
    CREATE TABLE v2.SECTION (R_SECTION_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_SECTION_LIBELLE_ECRAN varchar(35) NOT NULL);
IF OBJECT_ID(N'v2.JUGE') IS NULL
    CREATE TABLE v2.JUGE (JUG_ID_JUG int NOT NULL PRIMARY KEY, JUG_CIVILITE varchar(7) NOT NULL, JUG_NOM varchar(35) NOT NULL, JUG_PRENOM varchar(20) NULL);
IF COL_LENGTH('v2.JUGE', 'JUG_ACTIF') IS NULL ALTER TABLE v2.JUGE ADD JUG_ACTIF bit NOT NULL DEFAULT (1);
IF OBJECT_ID(N'v2.COMPOSITION') IS NULL
    CREATE TABLE v2.COMPOSITION (CMPST_ID_CMAUD int NOT NULL PRIMARY KEY, CMPST_ID_ADNC int NOT NULL, CMPST_NUM_ORDRE smallint NOT NULL,
        CMPST_ID_PRTRP int NULL, CMPST_ID_GRASS int NOT NULL, CMPST_ID_PRQTR int NULL, CMPST_PAR_DEFAUT bit NOT NULL);
IF OBJECT_ID(N'v2.EVENEMENT_PROCEDURE_EN_ATTENTE') IS NULL
    CREATE TABLE v2.EVENEMENT_PROCEDURE_EN_ATTENTE (EVNPA_ID_EVNPA int NOT NULL PRIMARY KEY, EVNPA_ID_APPAF_DELIBERER int NULL,
        EVNPA_ID_APPAF_PRONONCER int NULL, EVNPA_CODE_EVE_PRO varchar(10) NOT NULL);
IF OBJECT_ID(N'v2.CODE_EVE_PRO') IS NULL
    CREATE TABLE v2.CODE_EVE_PRO (R_CODEEVEPRO_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_CODEEVEPRO_LIBELLE_ECRAN varchar(35) NOT NULL);
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_TYPE_EVE_PRO') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_TYPE_EVE_PRO varchar(1) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_AVEC_PIECE_NUMERISE_INSMES') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_AVEC_PIECE_NUMERISE_INSMES bit NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_NATURE_DOC_GED') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_NATURE_DOC_GED varchar(50) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_TYPE_DEPOSANT_GED') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_TYPE_DEPOSANT_GED varchar(5) NULL;
IF OBJECT_ID(N'v2.EVENEMENT_PROCEDURE') IS NULL
    CREATE TABLE v2.EVENEMENT_PROCEDURE (EVNPR_ID_EVNPR int NOT NULL PRIMARY KEY, EVNPR_ID_INSTN int NULL, EVNPR_NUM_ORDRE smallint NULL,
        EVNPR_CODE_EVE_PRO varchar(10) NOT NULL, EVNPR_DATE datetime NULL, EVNPR_SURVENU bit NULL, EVNPR_DELAI_EXPIRE bit NULL);
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_NUMERO_SOURCE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_NUMERO_SOURCE varchar(36) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_TYPE_EVE_PRO') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_TYPE_EVE_PRO varchar(1) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_AVEC_PIECE_NUMERISE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_AVEC_PIECE_NUMERISE bit NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_NATURE_DOC_GED') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_NATURE_DOC_GED varchar(50) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_TYPE_DEPOSANT_GED') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_TYPE_DEPOSANT_GED varchar(5) NULL;

-- Les references. TC17 classement ordinaire, TC17P prononce. Codes plumitif : J (jugement rendu, CX) et O (ordonnance rendue, PC
-- et REF), prononces ; J porte l'evenement EV17J. R17 renvoi a l'audience de la meme chambre (« = »), classement TC17 ; R17S
-- renvoi sans prochain appel ; D17 delibere (pas un renvoi) ; R17X renvoi NON utilisable en saisie. Chambres : C17 avec
-- composition obligatoire, C17B sans. La fenetre de recherche : INTERV_AUD_DATE_MIN_RETAUD = 10 (au lieu de 14) ;
-- INTERV_AUD_DATE_MAX_RETAUD absent : 0 par defaut. Les reglages PARAMETRAGE de RIG v2 sont repris dans soc.Reglage (SOC-003).
EXEC sp_executesql N'
INSERT INTO v2.TYPE_CLASSEMENT (R_TYPECLASSE_VALEUR, R_TYPECLASSE_LIBELLE_ECRAN, R_TYPECLASSE_PRONONCE) VALUES
    (''TC17'', ''Classement du banc'', 0), (''TC17P'', ''Prononcé du banc'', 1);
INSERT INTO v2.CODE_PLUMITIF (R_CODEPLUMIT_VALEUR, R_CODEPLUMIT_LIBELLE_ECRAN, R_CODEPLUMIT_UTILISABLE_SAISIE, R_CODEPLUMIT_CODE_EVE_PRO,
    R_CODEPLUMIT_AVEC_AUDIENCE, R_CODEPLUMIT_TYPE_CLASSEMENT, R_CODEPLUMIT_PRONONCE, R_CODEPLUMIT_CHAMBRE, R_CODEPLUMIT_RENVOI,
    R_CODEPLUMIT_DELIBERE, R_CODEPLUMIT_COMPATIBLE_CX, R_CODEPLUMIT_COMPATIBLE_PC, R_CODEPLUMIT_COMPATIBLE_REF) VALUES
    (''J'', ''Jugement rendu'', 1, ''EV17J'', NULL, NULL, 1, NULL, 0, 0, 1, 0, 0),
    (''O'', ''Ordonnance rendue'', 1, NULL, NULL, NULL, 1, NULL, 0, 0, 0, 1, 1),
    (''R17'', ''Renvoi du banc'', 1, NULL, ''1'', ''TC17'', 0, ''='', 1, 0, 1, 1, 0),
    (''R17S'', ''Renvoi sans audience'', 1, NULL, NULL, NULL, 0, NULL, 1, 0, 1, 1, 0),
    (''D17'', ''Délibéré du banc'', 1, NULL, ''1'', ''TC17P'', 0, NULL, 0, 1, 1, 1, 0),
    (''R17X'', ''Renvoi hors saisie'', 0, NULL, ''1'', ''TC17'', 0, NULL, 1, 0, 1, 1, 0);
INSERT INTO v2.CHAMBRE (R_CHAMBRE_VALEUR, R_CHAMBRE_LIBELLE_ECRAN, R_CHAMBRE_AVEC_COMPO) VALUES
    (''C17'', ''Première du banc'', 1), (''C17B'', ''Sans composition'', 0);
INSERT INTO v2.SECTION (R_SECTION_VALEUR, R_SECTION_LIBELLE_ECRAN) VALUES (''S17'', ''Commerciale'');
INSERT INTO v2.JUGE (JUG_ID_JUG, JUG_CIVILITE, JUG_NOM, JUG_PRENOM, JUG_ACTIF) VALUES (1700301, ''MR'', ''JUGEBANC'', ''Paul'', 1);
INSERT INTO v2.CODE_EVE_PRO (R_CODEEVEPRO_VALEUR, R_CODEEVEPRO_LIBELLE_ECRAN, R_CODEEVEPRO_TYPE_EVE_PRO, R_CODEEVEPRO_AVEC_PIECE_NUMERISE_INSMES)
    VALUES (''EV17J'', ''Jugement du banc'', ''S'', 0);
INSERT INTO soc.Reglage (Code, Libelle, Valeur) VALUES (''INTERV_AUD_DATE_MIN_RETAUD'', ''Jours avant (banc)'', ''10'');';

